  "date-input",
  "date-time-input",
  "tabs",
  "skeleton-loader",
  "segmented-control",
  "form-field",
  "menu",
];

// Components with hand-authored entry points — the generator skips these.
const BEHAVIORAL_COMPONENTS = new Set([
  "menu",
  "form-field",
  "tree-browser",
  "alert",
  "avatar",
  "close-button",
  "modal",
  "tooltip",
  "in-place-edit",
  "progress-circle",
  "truncate",
  "tabs",
  "skeleton-loader",
  "segmented-control",
]);

// Components that require command event handling
const COMMAND_COMPONENTS = new Set([
  "button",
  "icon-button",
  "toggle-button",
  "calendar",
  "drilldown",
  "pages",
  "drawer-layout",
  "date-input",
  "date-time-input",
]);

function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/gu, (_, c: string) => c.toUpperCase());
}

function toClassName(name: string): string {
  return `pfx-${name}`;
}

const componentsDir = resolve(import.meta.dirname, "../src/components");

for (const component of ALL_COMPONENTS) {
  const className = toClassName(component);
  const isCommandComponent = COMMAND_COMPONENTS.has(component);

  if (BEHAVIORAL_COMPONENTS.has(component)) {
    console.log(`↷ skipped ${component}.ts (hand-authored)`);
    continue;
  }

  let content = `// fallow-ignore-file unused-file\n`;
  content += `/* c8 ignore file */ // side-effect module, tested via behavior functions and IIFE bundles\n`;
  content += `// Per-component interaction entry point for ${component}\n\n`;
  content += `import { applySpacing } from "../shared/index.js";\nimport { sel } from "../shared/prefix.js";\n`;

  if (isCommandComponent) {
    content += `import { syncInvoker } from "../shared/index.js";\n`;
  }

  content += `\n`;
  content += `// Initialize on page load\n`;
  content += `function init${toCamelCase(component)}() {\n`;
  content += `  for (const el of document.querySelectorAll(sel(".${className}"))) {\n`;
  content += `    applySpacing(el as HTMLElement);\n`;

  if (isCommandComponent) {
    content += `    syncInvoker(el as HTMLElement);\n`;
  }

  content += `  }\n`;
  content += `}\n\n`;
  content += `if (document.readyState === "loading") {\n`;
  content += `  document.addEventListener("DOMContentLoaded", init${toCamelCase(component)});\n`;
  content += `} else {\n`;
  content += `  init${toCamelCase(component)}();\n`;
  content += `}\n`;

  const filePath = join(componentsDir, `${component}.ts`);
  writeFileSync(filePath, content);
  console.log(`✓ generated ${component}.ts`);
}

console.log(`\n✓ Generated ${ALL_COMPONENTS.length} per-component interaction files`);

