           <dt>{{ t?.catalogIdLabel }}</dt>
           <dd>
             <code>{{ catalog.catalogId }}</code>
           </dd>
         </div>
       </dl>
     </section>

     <section class="a2ui-catalog__support" aria-labelledby="a2ui-support-heading">
       <h2 id="a2ui-support-heading" class="instui-heading -level-h2">
